/**
 * Tests the rounding performed by the {@link GridExtent#GridExtent(AbstractEnvelope,
 * GridRoundingMode, int[], int[], GridExtent, int[])} constructor.
 */
@Test
public void testRoundings() {
    final GeneralEnvelope env = new GeneralEnvelope(6);
    // Round to [1…3), stored as [1…2].
    env.setRange(0, 1.49999, 3.49998);
    // Round to [2…3), stored as [1…2] (not [2…2]) because the span is close to 2.
    env.setRange(1, 1.50001, 3.49998);
    // Round to [1…4), stored as [1…2] (not [1…3]) because the span is close to 2.
    env.setRange(2, 1.49998, 3.50001);
    // Round to [1…4), stored as [2…3] because the upper part is closer to integer.
    env.setRange(3, 1.49999, 3.50002);
    // Round to [1…4), stores as [1…3] because the span is not close enough to integer.
    env.setRange(4, 1.2, 3.8);
    GridExtent extent = new GridExtent(env, GridRoundingMode.NEAREST, GridClippingMode.STRICT, null, null, null, null);
    assertExtentEquals(extent, 0, 1, 2);
    assertExtentEquals(extent, 1, 1, 2);
    assertExtentEquals(extent, 2, 1, 2);
    assertExtentEquals(extent, 3, 2, 3);
    assertExtentEquals(extent, 4, 1, 3);
    // Unitialized envelope values were [0…0].
    assertExtentEquals(extent, 5, 0, 0);
}

