 */
@Test
public void testFromExtentAndDisplayEnvelope() {
    final GeneralEnvelope aoi = new GeneralEnvelope(HardCodedCRS.WGS84_LATITUDE_FIRST);
    aoi.setRange(1, 40, 55);
    aoi.setRange(0, -10, 70);
