    final Rectangle region = ImageUtilities.getBounds(image);
    // Exclude 4 columns on left side.
    region.x += 4;
    // Exclude 2 columns on right side.
    region.width -= 6;
    // Exclude 1 row on top.
    region.y += 1;
    // Exclude 2 rows on bottom.
    region.height -= 3;
    assertValuesEqual(image.getData(region), 0, new int[][] { { 211, 212, 310, 311, 312, 410 }, { 601, 602, 700, 701, 702, 800 }, { 611, 612, 710, 711, 712, 810 } });
}

