 */
@Test
public void testStateEditable() {
    // Shall be a no-op.
    assertFalse("transitionTo", md.transitionTo(ModifiableMetadata.State.EDITABLE));
    assertEquals("state", ModifiableMetadata.State.EDITABLE, md.state());
