    /*
         * When the parameter is part of a larger element, we expect a simplification.
         * Here, the URI should be omitted because it is a long value which does not
         * bring new information, since it is computed from other values.
         */
    final DefaultParameterDescriptorGroup group = new DefaultParameterDescriptorGroup(Collections.singletonMap(NAME_KEY, "Affine"), 1, 1, descriptor);
    assertWktEquals("PARAMETERGROUP[“Affine”,\n" + "  PARAMETER[“A0”, ID[“EPSG”, 8623]]]", group);
}

