    assertEquals("intValue", 3, parameter.intValue());
    assertEquals("doubleValue", 3, parameter.doubleValue(), STRICT);
    assertEquals("doubleValue", 300, parameter.doubleValue(Units.CENTIMETRE), STRICT);
