/**
 * Tests the formatting of a parameter value group with a cardinality
 * invalid according ISO 19111, but allowed by Apache SIS implementation.
 * ISO 19111 restricts {@link ParameterValue} cardinality to the [0 … 1] range,
 * but SIS can handle arbitrary number of occurrences (2 in this test).
 */
@Test
@DependsOnMethod("testExtendedCardinality")
public void testMultiOccurrence() {
    final ParameterValueGroup group = DefaultParameterDescriptorGroupTest.M1_M1_O1_O2.createValue();
    group.parameter("Mandatory 2").setValue(20);
    final ParameterValue<?> value = group.parameter("Optional 4");
    value.setValue(40);
    /*
         * Adding a second occurrence of the same parameter.
         * Not straightforward because not allowed by ISO 19111.
         */
    final ParameterValue<?> secondOccurrence = value.getDescriptor().createValue();
    group.values().add(secondOccurrence);
    secondOccurrence.setValue(50);
    final ParameterFormat format = new ParameterFormat(null, null);
    format.setContentLevel(ParameterFormat.ContentLevel.BRIEF);
    final String text = format.format(group);
    assertMultilinesEquals("Test group\n" + "┌─────────────┬─────────┬──────────────┬───────┐\n" + "│ Name        │ Type    │ Value domain │ Value │\n" + "├─────────────┼─────────┼──────────────┼───────┤\n" + "│ Mandatory 1 │ Integer │              │    10 │\n" + "│ Mandatory 2 │ Integer │              │    20 │\n" + "│ Optional 4  │ Integer │              │    40 │\n" + "│      ″      │    ″    │      ″       │    50 │\n" + "└─────────────┴─────────┴──────────────┴───────┘\n", text);
}

/**
 * Tests (un)marshalling of a parameter descriptor.
 *
 * @throws JAXBException if an error occurred during marshalling or unmarshalling.
 */
@Test
public void testDescriptor() throws JAXBException {
    final DefaultParameterDescriptor<Double> descriptor = new DefaultParameterDescriptor<>(Collections.singletonMap(DefaultParameterDescriptor.NAME_KEY, "A descriptor"), 0, 1, Double.class, null, null, null);
    final String xml = XML.marshal(descriptor);
    assertXmlEquals("<gml:OperationParameter xmlns:gml=\"" + Namespaces.GML + "\">\n" + "  <gml:name>A descriptor</gml:name>\n" + "  <gml:minimumOccurs>0</gml:minimumOccurs>\n" + "</gml:OperationParameter>", xml, "xmlns:*");
    final DefaultParameterDescriptor<?> r = (DefaultParameterDescriptor<?>) XML.unmarshal(xml);
    assertEquals("name", "A descriptor", r.getName().getCode());
    assertEquals("minimumOccurs", 0, r.getMinimumOccurs());
    assertEquals("maximumOccurs", 1, r.getMaximumOccurs());
    /*
         * A DefaultParameterDescriptor with null 'valueClass' is illegal, but there is no way we can guess
         * this information if the <gml:OperationParameter> element was not a child of <gml:ParameterValue>.
         * The current implementation leaves 'valueClass' to null despite being illegal. This behavior may
         * change in any future Apache SIS version.
         */
    assertNull("valueDomain", r.getValueDomain());
    // May change in any future SIS release.
    assertNull("valueClass", r.getValueClass());
}

