/**
 * Tests {@link AbstractCS#forConvention(AxesConvention)}
 * with a {@link AxesConvention#NORMALIZED} argument.
 */
@Test
@DependsOnMethod("testForRightHandedConvention")
public void testForNormalizedConvention() {
    /*
         * Some expected axes, identical to the ones in HardCodedAxes except for name or units.
         * We verify the properties inferred by the constructor as a matter of principle, even
         * if it is not really the purpose of this test.
         */
    final DefaultCoordinateSystemAxis EASTING = new DefaultCoordinateSystemAxis(singletonMap(NAME_KEY, Vocabulary.format(Vocabulary.Keys.Unnamed)), "E", AxisDirection.EAST, Units.METRE);
    final DefaultCoordinateSystemAxis HEIGHT = new DefaultCoordinateSystemAxis(singletonMap(NAME_KEY, "Height"), "h", AxisDirection.UP, Units.METRE);
    assertEquals("minimumValue", Double.NEGATIVE_INFINITY, EASTING.getMinimumValue(), STRICT);
    assertEquals("maximumValue", Double.POSITIVE_INFINITY, EASTING.getMaximumValue(), STRICT);
    assertNull("rangeMeaning", EASTING.getRangeMeaning());
    assertEquals("minimumValue", Double.NEGATIVE_INFINITY, HEIGHT.getMinimumValue(), STRICT);
    assertEquals("maximumValue", Double.POSITIVE_INFINITY, HEIGHT.getMaximumValue(), STRICT);
    assertNull("rangeMeaning", HEIGHT.getRangeMeaning());
    /*
         * Now the actual test. First we opportunistically test RIGHT_HANDED and DISPLAY_ORIENTED
         * before to test NORMALIZED, in order to test in increasing complexity.
         */
    final AbstractCS cs = new AbstractCS(singletonMap(NAME_KEY, "Test"), HardCodedAxes.TIME, HardCodedAxes.NORTHING, HardCodedAxes.WESTING, HardCodedAxes.HEIGHT_cm);
    verifyAxesConvention(AxesConvention.RIGHT_HANDED, cs, HardCodedAxes.NORTHING, HardCodedAxes.WESTING, HardCodedAxes.HEIGHT_cm, HardCodedAxes.TIME);
    verifyAxesConvention(AxesConvention.DISPLAY_ORIENTED, cs, EASTING, HardCodedAxes.NORTHING, HardCodedAxes.HEIGHT_cm, HardCodedAxes.TIME);
    verifyAxesConvention(AxesConvention.NORMALIZED, cs, EASTING, HardCodedAxes.NORTHING, HEIGHT, HardCodedAxes.TIME);
}

