    assertEquals(90, dir.meridian, 0);
    assertEquals(name, dir.toString());
    assertEquals(dir, DirectionAlongMeridian.parse("South along 90 deg East"));
    name = "South along 90°W";
    dir = DirectionAlongMeridian.parse(name);
