/**
 * Tests the {@link Initializer#radiusOfConformalSphere(double)} method.
 * This test computes the Radius of Conformal Sphere using the values given by the
 * IOGP Report 373-07-02 – <cite>Coordinate conversions and transformation including formulas</cite>
 * for the <cite>Amersfoort / RD New</cite> projection (a Stereographic one).
 */
@Test
public void testRadiusOfConformalSphere() {
    final OperationMethod op = new ObliqueStereographic();
    final ParameterValueGroup p = op.getParameters().createValue();
    /*
         * Following parameters are not given explicitly by EPSG definitions since they are
         * usually inferred from the datum.  However in the particular case of this test, we
         * need to provide them. The names used below are either OGC names or SIS extensions.
         */
    p.parameter("semi_major").setValue(6377397.155);
    p.parameter("inverse_flattening").setValue(299.15281);
    /*
         * Following parameters are reproduced verbatim from EPSG repository and EPSG guide.
         */
    p.parameter("Latitude of natural origin").setValue(52.156160556);
    p.parameter("Longitude of natural origin").setValue(5.387638889);
    p.parameter("Scale factor at natural origin").setValue(0.9999079);
    p.parameter("False easting").setValue(155000.00);
    p.parameter("False northing").setValue(463000.00);
    /*
         * The following lines are a typical way to create an Initializer instance.
         * The EnumMap tells to the Initializer constructor which parameters to look for.
         * We construct this map here for testing purpose, but users normally do not have
         * to do that since this map is provided by the ObliqueStereographic class itself.
         */
    final EnumMap<NormalizedProjection.ParameterRole, ParameterDescriptor<Double>> roles = new EnumMap<>(NormalizedProjection.ParameterRole.class);
    roles.put(NormalizedProjection.ParameterRole.CENTRAL_MERIDIAN, ObliqueStereographic.LONGITUDE_OF_ORIGIN);
    roles.put(NormalizedProjection.ParameterRole.SCALE_FACTOR, ObliqueStereographic.SCALE_FACTOR);
    roles.put(NormalizedProjection.ParameterRole.FALSE_EASTING, ObliqueStereographic.FALSE_EASTING);
    roles.put(NormalizedProjection.ParameterRole.FALSE_NORTHING, ObliqueStereographic.FALSE_NORTHING);
    final Initializer initializer = new Initializer(op, (Parameters) p, roles, NormalizedProjection.STANDARD_VARIANT);
    /*
         * The following lines give an example of how Apache SIS projection constructors
         * use the Initializer class.
         */
    final double φ0 = toRadians(initializer.getAndStore(ObliqueStereographic.LATITUDE_OF_ORIGIN));
    assertTrue(φ0 > 0);
    assertEquals("Conformal Sphere Radius", 6382644.571, 6377397.155 * initializer.radiusOfConformalSphere(sin(φ0)), Formulas.LINEAR_TOLERANCE);
}

/**
 * Verifies the value of the constant used in <cite>"Lambert Conic Conformal (2SP Belgium)"</cite> projection.
 *
 * @see #testLambertConicConformalBelgium()
 */
@Test
public void verifyBelgeConstant() {
    final DoubleDouble BELGE_A = (DoubleDouble) LambertConicConformal.belgeA();
    BigDecimal a = new BigDecimal(BELGE_A.value);
    a = a.add(new BigDecimal(BELGE_A.error));
    // Conversion from radians to degrees.
    a = a.multiply(new BigDecimal("57.29577951308232087679815481410517"));
    // Conversion from degrees to seconds.
    a = a.multiply(new BigDecimal(60 * 60));
    // The standard value.
    a = a.add(new BigDecimal("29.2985"));
    assertTrue(abs(a.doubleValue()) < 1E-31);
}

/**
 * Tests the WKT formatting of {@link NormalizedProjection}. For the Lambert Conformal projection, we expect
 * the internal {@code n} parameter in addition to the eccentricity.
 *
 * <h4>Note on accuracy</h4>
 * The value of the eccentricity parameter should be fully accurate because it is calculated using only the
 * {@link Math#sqrt(double)} function (ignoring basic algebraic operations) which, according javadoc, must
 * give the result closest to the true mathematical result. But the functions involved in the calculation of
 * <var>n</var> do not have such strong guarantees. So we use a regular expression in this test for ignoring
 * the 2 last digits of <var>n</var>.
 */
@Test
public void testNormalizedWKT() {
    createNormalizedProjection(true, 40);
    assertWktEqualsRegex("(?m)\\Q" + "PARAM_MT[“Lambert conic conformal (radians domain)”,\n" + "  PARAMETER[“eccentricity”, 0.0818191908426215],\n" + // 0.6427876096865393 in the original test.
    "  PARAMETER[“n”, 0.64278760968653\\E\\d*\\Q]]\\E");
}

/**
 * Tests the projection at some special latitudes (0, ±π/2, NaN and others).
 *
 * @throws ProjectionException if an error occurred while projecting a point.
 */
@Test
public void testSpecialLatitudes() throws ProjectionException {
    if (transform == null) {
        // May have been initialized by 'testSphericalCase'.
        // Elliptical case
        createNormalizedProjection(true, 40);
    }
    final double INF = POSITIVE_INFINITY;
    assertEquals("Not a number", NaN, transform(NaN), NORMALIZED_TOLERANCE);
    assertEquals("Out of range", NaN, transform(+2), NORMALIZED_TOLERANCE);
    assertEquals("Out of range", NaN, transform(-2), NORMALIZED_TOLERANCE);
    assertEquals("Forward 0°N", 1, transform(0), NORMALIZED_TOLERANCE);
    assertEquals("Forward 90°S", 0, transform(-PI / 2), NORMALIZED_TOLERANCE);
    assertEquals("Forward 90°N", INF, transform(+PI / 2), NORMALIZED_TOLERANCE);
    assertEquals("Forward (90+ε)°S", 0, transform(nextDown(-PI / 2)), NORMALIZED_TOLERANCE);
    assertEquals("Forward (90+ε)°N", INF, transform(nextUp(+PI / 2)), NORMALIZED_TOLERANCE);
    assertEquals("Forward (90-ε)°S", 0, transform(nextUp(-PI / 2)), 1E-10);
    assertEquals("Not a number", NaN, inverseTransform(NaN), NORMALIZED_TOLERANCE);
    assertEquals("Inverse 0", -PI / 2, inverseTransform(0), NORMALIZED_TOLERANCE);
    assertEquals("Inverse +1", 0, inverseTransform(+1), NORMALIZED_TOLERANCE);
    assertEquals("Inverse -1", 0, inverseTransform(-1), NORMALIZED_TOLERANCE);
    assertEquals("Inverse +∞", +PI / 2, inverseTransform(INF), NORMALIZED_TOLERANCE);
    assertEquals("Inverse −∞", +PI / 2, inverseTransform(-INF), NORMALIZED_TOLERANCE);
    // Like the north case, but with sign inversed.
    createNormalizedProjection(((LambertConicConformal) transform).eccentricity != 0, -40);
    validate();
    assertEquals("Not a number", NaN, transform(NaN), NORMALIZED_TOLERANCE);
    assertEquals("Out of range", NaN, transform(+2), NORMALIZED_TOLERANCE);
    assertEquals("Out of range", NaN, transform(-2), NORMALIZED_TOLERANCE);
    assertEquals("Forward 0°N", 1, transform(0), NORMALIZED_TOLERANCE);
    assertEquals("Forward 90°N", INF, transform(+PI / 2), NORMALIZED_TOLERANCE);
    assertEquals("Forward 90°S", 0, transform(-PI / 2), NORMALIZED_TOLERANCE);
    assertEquals("Forward (90+ε)°N", INF, transform(nextUp(+PI / 2)), NORMALIZED_TOLERANCE);
    assertEquals("Forward (90+ε)°S", 0, transform(nextDown(-PI / 2)), NORMALIZED_TOLERANCE);
    assertEquals("Forward (90-ε)°S", 0, transform(nextUp(-PI / 2)), 1E-10);
    assertEquals("Not a number", NaN, inverseTransform(NaN), NORMALIZED_TOLERANCE);
    assertEquals("Inverse 0", -PI / 2, inverseTransform(0), NORMALIZED_TOLERANCE);
    assertEquals("Inverse +∞", +PI / 2, inverseTransform(INF), NORMALIZED_TOLERANCE);
    assertEquals("Inverse −∞", +PI / 2, inverseTransform(-INF), NORMALIZED_TOLERANCE);
}

