 */
@Test
public void testAddAndRemoveToMultiValuesMap() {
    final Map<String, List<Integer>> map = new LinkedHashMap<>();
    final Integer A1 = 2;
    final Integer A2 = 4;
    final Integer B1 = 3;
    final Integer B2 = 6;
    final Integer B3 = 9;
