    for (int i = 0; i < NUMBER_OF_REPETITIONS; i++) {
        double a = nextRandom();
        double b = nextRandom();
        if (abs(a) < abs(b)) {
            final double t = a;
            a = b;
            b = t;
        }
        dd.value = a;
        dd.error = b;
        dd.normalize();
        assertNormalizedAndEquals(a + b, dd);
        assertExtendedEquals(new BigDecimal(a).add(new BigDecimal(b)), dd, ADD_TOLERANCE_FACTOR);
    }
}

