 * Usually the exponentiation is implicit, as in {@code "m*s-1"}.
 * However some formats write it explicitly, as in {@code "m*s^-1"}.
 */
@Test
@DependsOnMethod("testParseMultiplier")
public void testParseExponentiation() {
