    assertFalse("A-1", isUnicodeIdentifier("A-1"));
    assertFalse("A+1", isUnicodeIdentifier("A+1"));
    assertFalse("A/1", isUnicodeIdentifier("A/1"));
    assertFalse("A\\1", isUnicodeIdentifier("A\\1"));
    assertFalse("A*1", isUnicodeIdentifier("A*1"));
    assertFalse("A.1", isUnicodeIdentifier("A.1"));
    assertFalse("A,1", isUnicodeIdentifier("A,1"));
    assertFalse("A:1", isUnicodeIdentifier("A:1"));
    assertFalse("A;1", isUnicodeIdentifier("A;1"));
    assertFalse("A#1", isUnicodeIdentifier("A#1"));
    assertFalse("A?1", isUnicodeIdentifier("A?1"));
    assertFalse("A!1", isUnicodeIdentifier("A!1"));
    // Degree
    assertFalse("A°1", isUnicodeIdentifier("A°1"));
    // Masculine ordinal
    assertTrue("Aº1", isUnicodeIdentifier("Aº1"));
