    assertNull(weakMap.put(k3, v3));
    assertSame(v3, weakMap.put(k3, v3));
    assertSame(v1, weakMap.get(k1));
    assertSame(v2, weakMap.get(k2));
    assertSame(v3, weakMap.get(k3));
