 */
@Test
public void testSeekOnForwardOnlyChannel() throws IOException {
    int length = random.nextInt(2048) + 1024;
    final byte[] array = createRandomArray(length);
    // Safety against buffer underflow.
    length -= Long.BYTES;
    final ByteBuffer buffer = ByteBuffer.wrap(array);
    final ChannelDataInput input = new ChannelDataInput("testSeekOnForwardOnlyChannel", new DripByteChannel(array, random, 1, 2048), ByteBuffer.allocate(random.nextInt(64) + 16), false);
    int position = 0;
