/**
 * Tests {@link RewindableLineReader#rewind()}.
 *
 * @throws IOException if an error occurred while reading characters.
 */
@Test
public void testRewind() throws IOException {
    RewindableLineReader reader = reader();
    // Use a smaller limit for testing sooner mark invalidation.
    reader.mark(TRANSFERT_SIZE);
    assertEquals("charAt(0)", 'A', reader.read());
    assertEquals("charAt(1)", 'B', reader.read());
    assertEquals("charAt(2)", 'C', reader.read());
    /*
         * Since we have read less than 100 characters, RewindableLineReader.rewind()
         * should be able to successfully delegate the work to BufferedReader.reset().
         */
    assertSame("BufferedReader.reset() should have succeeded.", reader, reader.rewind());
    assertEquals("charAt(0)", 'A', reader.read());
    assertEquals("charAt(1)", 'B', reader.read());
    assertEquals("charAt(2)", 'C', reader.read());
    assertEquals("charAt(3)", 'D', reader.read());
    /*
         * Skip a number of characters greater than the current buffer content. It should cause BufferedReader to
         * invalidate the mark. As a result of failure to execute BufferedReader.reset(), the 'reader' variable
         * should get a new value. However while we expect the value to change, we do not require it since whether
         * BufferedReader.reset() succeeded or not depends on BufferedReader implementation.
         */
    reader.skip(2 * TRANSFERT_SIZE);
    assertEquals("charAt(…)", 'W', reader.read());
    final RewindableLineReader old = reader;
    // Should be a new instance, but this is not mandatory.
    reader = reader.rewind();
    if (reader != old)
        try {
            old.read();
            fail("Old reader should be closed.");
        } catch (IOException e) {
            // This is the expected exception.
        }
    assertEquals("charAt(0)", 'A', reader.read());
    assertEquals("charAt(1)", 'B', reader.read());
    assertEquals("charAt(2)", 'C', reader.read());
    assertEquals("charAt(3)", 'D', reader.read());
    reader.close();
}

/**
 * Tests inner join feature set.
 *
 * @throws DataStoreException if an error occurred while creating the feature set.
 */
@Test
public void testInnerJoin() throws DataStoreException {
    final FeatureSet col = create(JoinFeatureSet.Type.INNER);
    try (Stream<Feature> stream = stream(col)) {
        final Iterator<Feature> ite = stream.iterator();
        int count = 0;
        while (ite.hasNext()) {
            count++;
            final Feature f = ite.next();
            // Expected value of "att1".
            final String att1;
            // Expected value of "att2" and "att3", on which the join operation is done.
            final int join;
            // Expected value of "att4".
            final double att4;
            switch(getId(f)) {
                case "fid_1_0 fid_2_0":
                    att1 = "str1";
                    join = 1;
                    att4 = 10;
                    break;
                case "fid_1_1 fid_2_1":
                    att1 = "str2";
                    join = 2;
                    att4 = 20;
                    break;
                case "fid_1_1 fid_2_2":
                    att1 = "str2";
                    join = 2;
                    att4 = 30;
                    break;
                case "fid_1_2 fid_2_3":
                    att1 = "str3";
                    join = 3;
                    att4 = 40;
                    break;
                default:
                    fail("unexpected feature");
                    continue;
            }
            final Feature c1 = (Feature) f.getPropertyValue("s1");
            final Feature c2 = (Feature) f.getPropertyValue("s2");
            assertEquals("att1", att1, c1.getProperty("att1").getValue());
            assertEquals("att2", join, c1.getProperty("att2").getValue());
            assertEquals("att3", join, c2.getProperty("att3").getValue());
            assertEquals("att4", att4, c2.getProperty("att4").getValue());
        }
        assertEquals("Unexpected amount of features.", 4, count);
    }
}

